import json,os,sys,re,math
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from lib import *
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT=f'{ROOT}/courses/scada'
course={"id":"scada","name":"SCADA-жүйелер","lang":"kk","space":"courses"}
def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items):return '<ul>'+''.join(f'<li>{i}</li>' for i in items)+'</ul>'
def OL(items):return '<ol>'+''.join(f'<li>{i}</li>' for i in items)+'</ol>'
def LN(d,c='ln'):return f'<path d="{d}" class="{c}"/>'
def R(x,y,w,h,c='bx',r=3):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" class="{c}"/>'
def PL(pts,c='ln'):return f'<polyline points="{" ".join(f"{x:.0f},{y:.0f}" for x,y in pts)}" class="{c}" fill="none"/>'

def fi(n):return f'{n:,}'.replace(',',' ')
def ff(x):return f'{x:,.1f}'.replace(',',' ').replace('.',',')
# ---------- numbers (recomputed) ----------
rec_1s=500*86400;rec_1m=500*1440
assert (rec_1s,rec_1m,rec_1s//rec_1m)==(43200000,720000,60)
rec2_1s=200*86400;rec2_1m=200*1440;assert (rec2_1s,rec2_1m)==(17280000,288000)
e0,e1=12840.5,12998.3;E=round(e1-e0,1);assert E==157.8
def interp(pts,t):
    for (a,va),(b,vb) in zip(pts,pts[1:]):
        if a<=t<=b:return va+(vb-va)*(t-a)/(b-a) if b>a else vb
sp=[(0,20),(20,20),(26,23),(45,23),(50,21),(60,21)]
v=[interp(sp,t) for t in range(61)]
per=list(range(0,61,6))
chg=[];last=None
for t in range(61):
    if last is None or abs(v[t]-last)>=0.5:chg.append(t);last=v[t]
cond=list(range(20,31,2))
assert len(per)==11 and 0<len(chg)<len(per) and len(cond)==6,(len(per),len(chg),len(cond))
NP,NC,NK=len(per),len(chg),len(cond)

