f_live=F(fig_live(),'Тек қазіргі мән «не болды?» дегенге жауап бермейді, ал архив жауап береді (мысал үшін)')

def fig_modes():
    X=lambda t:30+t*5;Y=lambda val:70-(val-20)*10
    o=PL([(X(t),Y(v[t])) for t in range(61)])+LN('M30 80 L330 80')
    rows=[(f'Уақыт аралығымен: {NP} жазба',per,102),(f'Өзгеру кезінде (≥ 0,5 °C): {NC} жазба',chg,138),(f'Шарт бойынша (сорғы жұмыс істегенде): {NK} жазба',cond,174)]
    for lab,ts,y in rows:
        o+=TL(30,y-6,lab,'t-s')+R(30,y,300,14,'bx',2)
        for t in ts:o+=f'<circle cx="{X(t)}" cy="{y+7}" r="3" class="hda"/>'
    o+=T(170,208,'сигнал — баяу өзгеретін температура (мысал үшін)','t-s mu')
    return S(340,218,o,'Архивтеу тәсілдері: уақыт аралығымен, мән өзгерген кезде және шарт бойынша; әр тәсіл әртүрлі жазба санын береді')
f_modes=F(fig_modes(),'Бір сигнал — үш тәсіл: жазба саны әртүрлі')

